module SerialNumberField
  module IssuePatch
    extend ActiveSupport::Concern

    included do
      before_validation :restore_serial_number_values
      after_save :assign_serial_number!
    end

    # Serial numbers are generated by the server, never supplied by a form/API.
    # Copying a ticket starts with blank values; later saves retain its number.
    def restore_serial_number_values
      serial_values = custom_field_values.select do |value|
        value.custom_field.field_format == SerialNumberField::Format::NAME
      end
      return if serial_values.empty?

      values = new_record? ? {} : CustomValue.where(
        customized_type: 'Issue', customized_id: id,
        custom_field_id: serial_values.map(&:custom_field_id)
      ).pluck(:custom_field_id, :value).to_h
      serial_values.each do |value|
        value.value = values.fetch(value.custom_field_id, '')
      end
    end

    def assign_serial_number!
      # All fields are locked in the same order until the issue transaction
      # commits. Separate processes allocating a shared field must see the
      # previous committed number before calculating the next one.
      fields = serial_number_fields.sort_by(&:id)
      return if fields.empty?

      fields.each do |field|
        target = serial_number_custom_value(field)
        next unless target && target.value.blank?

        field.with_lock do
          target.reload
          next unless target.value.blank?

          target.update!(value: field.format.generate_value(field, self))
        end
      end
      # Redmine caches both CustomValue records and their form wrappers.
      # Discard the pre-allocation values so a second save cannot erase them.
      custom_values.reset
      @custom_field_values = nil
    end

    def serial_number_custom_value(field)
      CustomValue.find_by(custom_field_id: field.id, customized_type: 'Issue', customized_id: id)
    end

    def serial_number_fields
      editable_custom_fields.select do |field|
        field.field_format == SerialNumberField::Format::NAME
      end
    end
  end
end
